/* ---- mapeamento linha crua -> objeto ---- */
function rowsToObjects(rows,keys){return rows.map(r=>{const o={};keys.forEach((k,i)=>o[k]=r[i]);return o})}
const BASE_TUB_KEYS=['desenho','item','descDet','descricao','folha','qtdPrevista','und','dn','pesoUnit','pesoTotal','pesoTotalT'];
const SUPORTES_KEYS=['desenho','xx','item','nivel','quantidade','unidade','descricao','pesoUnit','pesoTotal','especMaterial','observacao'];
const TAKEOFF_KEYS=['item','qte','descricao','material','pesoUnit','pesoTotal','observacao','desenhoNo'];
const ORDEM_SERVICO_KEYS=['item','totHist'];

function buildDefaultControle(){
  return {
    baseTubulacao: rowsToObjects(RAW_BASE_TUB,BASE_TUB_KEYS).map((r,i)=>({id:'bt'+i,...r})),
    suporte: rowsToObjects(RAW_SUPORTES,SUPORTES_KEYS).map((r,i)=>({id:'sp'+i,...r})),
    suportePorPlanta: RAW_SUPORTE_PLANTA.map((r,i)=>{
      const o={id:'spp'+i,desenho:r[0],item:r[1]};
      PLANTA_CODES.forEach((c,ci)=>o[c]=r[2+ci]);
      o.total=r[2+PLANTA_CODES.length];
      return o;
    }),
    takeoff: rowsToObjects(RAW_TAKEOFF,TAKEOFF_KEYS).map((r,i)=>({id:'to'+i,...r})),
    ordemServico: rowsToObjects(RAW_ORDEM_SERVICO,ORDEM_SERVICO_KEYS).map((r,i)=>({id:'os'+i,...r}))
  };
}

const CONTROLE_KEY='gestaoos_controle_v1';
let CONTROLE=null;
function loadControleFromCache(){
  try{
    const raw=localStorage.getItem(CONTROLE_KEY);
    if(raw){
      CONTROLE=JSON.parse(raw);
      const defaults=buildDefaultControle();
      let migrated=false;
      Object.keys(defaults).forEach(k=>{if(!CONTROLE[k]){CONTROLE[k]=defaults[k];migrated=true}});
      if(migrated)saveControle();
      return;
    }
  }catch(e){}
  CONTROLE=buildDefaultControle();
  saveControle();
}
async function loadControle(){
  loadControleFromCache();
  if(!sessionProfile)return;
  if(!(await isSupabaseReachable())){supaErrToast({message:'servidor inacessível'},'Controle: usando dados salvos neste dispositivo');return}
  try{
    const keys=Object.keys(CONTROLE_TABLE_MAP);
    const results=await Promise.all(keys.map(k=>supabase.from(CONTROLE_TABLE_MAP[k]).select('*')));
    const errRes=results.find(r=>r.error);
    if(errRes)throw errRes.error;
    keys.forEach((k,i)=>{
      const rows=results[i].data;
      if(rows&&rows.length)CONTROLE[k]=rows.map(r=>controleRowFromDb(k,r));
    });
    saveControle();
  }catch(e){supaErrToast(e,'Controle: usando dados salvos neste dispositivo')}
}
function saveControle(){localStorage.setItem(CONTROLE_KEY,JSON.stringify(CONTROLE))}

