/* ---- DataGrid genérico (edição inline, exclusão, adição, colunas customizáveis) ---- */
function renderGrid(key,mountId){
  const def=GRID_DEFS[key];
  const cols=visibleColsFor(key);
  const rows=CONTROLE[key];
  const mount=document.getElementById(mountId);
  if(!mount)return;
  const theadCells=cols.map(c=>`<th>${esc(c.label)}</th>`).join('');
  const rowsHtml=rows.map(r=>gridRowHtml(key,r,cols)).join('');
  mount.innerHTML=`
    <div class="grid-toolbar">
      <div class="grid-count">${rows.length} registro(s)</div>
      <div class="grid-toolbar-right">
        <button class="btn secondary" onclick="gridExportExcel('${key}')" style="min-height:36px;padding:0 12px;font-size:12px">📥 Exportar</button>
        ${sessionProfile==='ADMIN'?`<button class="btn secondary" onclick="gridTriggerImport('${key}')" style="min-height:36px;padding:0 12px;font-size:12px">📤 Importar</button>`:''}
        ${sessionProfile==='ADMIN'?`<button class="btn secondary" onclick="controleSyncAllForKey('${key}')" style="min-height:36px;padding:0 12px;font-size:12px">🔄 Sincronizar</button>`:''}
        <div class="dd-wrap">
          <button class="btn secondary" onclick="gridOpenColsPopover('${key}')" style="min-height:36px;padding:0 12px;font-size:12px">⚙️ Colunas</button>
          <div class="dd-menu hidden grid-cols-popover" id="gridCols-${key}"></div>
        </div>
      </div>
    </div>
    ${gridAddFormHtml(key)}
    <div style="overflow-x:auto"><table class="cad-table"><thead><tr>${theadCells}<th></th></tr></thead>
    <tbody>${rowsHtml||'<tr><td colspan="'+(cols.length+1)+'" class="grid-empty">Nenhum registro.</td></tr>'}</tbody></table></div>`;
}
function gridRowHtml(key,row,cols){
  const editing=gridEditingKey===key&&gridEditingId===row.id;
  const cells=cols.map(c=>{
    if(editing){
      const inputType=c.type==='number'?'number':'text';
      const val=row[c.key];
      return `<td class="grid-edit-cell"><input id="gcell-${key}-${row.id}-${c.key}" type="${inputType}" ${c.type==='number'?'step="any"':''} value="${esc(val??'')}"></td>`;
    }
    let v=row[c.key];
    if(c.type==='number'&&typeof v==='number')v=fmtNum(v);
    return `<td>${esc(v??'')}</td>`;
  }).join('');
  const actions=editing
    ?`<button class="grid-icon-btn" title="Salvar" onclick="gridSaveRow('${key}','${row.id}')">✔️</button><button class="grid-icon-btn" title="Cancelar" onclick="gridCancelEdit()">✖️</button>`
    :(sessionProfile==='ADMIN'?`<button class="grid-icon-btn" title="Editar" onclick="gridEditRow('${key}','${row.id}')">✏️</button><button class="grid-icon-btn" title="Excluir" onclick="gridDeleteRow('${key}','${row.id}')">🗑️</button>`:'');
  return `<tr>${cells}<td><div class="grid-row-actions">${actions}</div></td></tr>`;
}
let gridFormOpen={};
function toggleGridForm(key){gridFormOpen[key]=!gridFormOpen[key];renderControle()}
function gridAddFormHtml(key){
  const def=GRID_DEFS[key];
  if(sessionProfile!=='ADMIN')return '';
  const open=!!gridFormOpen[key];
  const formHtml=open?`<div class="cad-form">${def.cols.map(c=>`<div class="qfield2"><label>${esc(c.label)}</label><input id="gadd-${key}-${c.key}" type="${c.type==='number'?'number':'text'}" ${c.type==='number'?'step="any"':''}></div>`).join('')}<button class="btn primary" onclick="gridSubmitAdd('${key}')">＋ Adicionar</button></div>`:'';
  return `<div style="margin-bottom:14px"><button class="btn secondary" onclick="toggleGridForm('${key}')" style="min-height:36px;padding:0 14px;font-size:12px">${open?'✕ Fechar cadastro':'＋ Cadastro'}</button>${formHtml}</div>`;
}
function gridParseVal(c,raw){
  if(c.type==='number'){if(raw===''||raw===null||raw===undefined)return 0;const n=parseFloat(String(raw).replace(',','.'));return isNaN(n)?0:n}
  return raw;
}
function gridEditRow(key,id){
  if(sessionProfile!=='ADMIN'){toast('Acesso restrito ao Administrador.','err');return}
  gridEditingKey=key;gridEditingId=id;renderControle();
}
function gridCancelEdit(){gridEditingKey=null;gridEditingId=null;renderControle()}
function gridSaveRow(key,id){
  const def=GRID_DEFS[key];
  const row=CONTROLE[key].find(r=>r.id===id);
  if(!row)return;
  def.cols.forEach(c=>{
    const el=document.getElementById('gcell-'+key+'-'+id+'-'+c.key);
    if(!el)return;
    row[c.key]=gridParseVal(c,el.value);
  });
  saveControle();
  gridEditingKey=null;gridEditingId=null;
  renderControle();
  toast('Registro atualizado.','ok');
  controleSyncRowUpdate(key,row);
}
async function gridDeleteRow(key,id){
  if(sessionProfile!=='ADMIN'){toast('Acesso restrito ao Administrador.','err');return}
  const ok=await askConfirm('Excluir registro','Esta ação não pode ser desfeita. Deseja excluir este registro?');
  if(!ok)return;
  const row=CONTROLE[key].find(r=>r.id===id);
  CONTROLE[key]=CONTROLE[key].filter(r=>r.id!==id);
  saveControle();
  renderControle();
  toast('Registro excluído.','ok');
  if(row?._id)controleSyncRowDelete(key,row._id);
}
function gridSubmitAdd(key){
  const def=GRID_DEFS[key];
  const entry={id:key.slice(0,3)+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)};
  let hasValue=false;
  def.cols.forEach(c=>{
    const el=document.getElementById('gadd-'+key+'-'+c.key);
    if(!el)return;
    const raw=el.value;
    if(raw)hasValue=true;
    entry[c.key]=gridParseVal(c,raw);
  });
  if(!hasValue){toast('Preencha ao menos um campo.','err');return}
  CONTROLE[key].push(entry);
  saveControle();
  renderControle();
  toast('Linha adicionada.','ok');
  controleSyncRowInsert(key,entry);
}

/* ---- Importar / Exportar Excel ---- */
function gridExportExcel(key){
  const def=GRID_DEFS[key];
  const data=CONTROLE[key].map(r=>{
    const o={};
    def.cols.forEach(c=>{o[c.label]=r[c.key]??''});
    return o;
  });
  const ws=XLSX.utils.json_to_sheet(data);
  const wb=XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb,ws,def.label.slice(0,31));
  XLSX.writeFile(wb,def.label.replace(/[\\/:*?"<>|]/g,'_')+'.xlsx');
}
function gridTriggerImport(key){
  if(sessionProfile!=='ADMIN'){toast('Acesso restrito ao Administrador.','err');return}
  const input=document.getElementById('gridImportInput');
  if(!input)return;
  input.dataset.targetKey=key;
  input.value='';
  input.click();
}
async function gridHandleImportFile(input){
  const key=input.dataset.targetKey;
  const file=input.files&&input.files[0];
  if(!file||!key)return;
  const def=GRID_DEFS[key];
  const ok=await askConfirm('Importar planilha','Isso vai SUBSTITUIR todos os registros de "'+def.label+'" pelos dados do arquivo selecionado ('+file.name+'). Deseja continuar?');
  if(!ok){input.value='';return}
  try{
    const buf=await file.arrayBuffer();
    const wb=XLSX.read(buf,{type:'array'});
    const ws=wb.Sheets[wb.SheetNames[0]];
    const rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:null,raw:true});
    let headerIdx=0;
    for(let i=0;i<Math.min(rows.length,6);i++){
      const rowVals=(rows[i]||[]).map(v=>String(v??'').trim().toLowerCase());
      if(def.cols.some(c=>rowVals.includes(c.label.toLowerCase()))){headerIdx=i;break}
    }
    const headerRow=(rows[headerIdx]||[]).map(v=>String(v??'').trim().toLowerCase());
    const colIndexFor=def.cols.map((c,ci)=>{
      const idx=headerRow.indexOf(c.label.toLowerCase());
      return idx>=0?idx:ci;
    });
    const dataRows=rows.slice(headerIdx+1).filter(r=>r&&r.some(v=>v!==null&&v!==''));
    const newEntries=dataRows.map((r,i)=>{
      const entry={id:key.slice(0,3)+'_imp'+Date.now().toString(36)+i};
      def.cols.forEach((c,ci)=>{
        let v=r[colIndexFor[ci]];
        entry[c.key]=gridParseVal(c,v===null||v===undefined?'':v);
      });
      return entry;
    });
    CONTROLE[key]=newEntries;
    saveControle();
    renderControle();
    toast(newEntries.length+' registro(s) importado(s) para '+def.label+'. Clique em "Sincronizar" para enviar ao servidor.','ok');
  }catch(e){
    toast('Erro ao importar arquivo: '+e.message,'err');
  }
  input.value='';
}

/* ---- customização de colunas (arrastar, exibir/ocultar, salvar) ---- */
function gridOpenColsPopover(key){
  gridColsDraftKey=key;
  const st=ensureColsState(key);
  gridColsDraft={order:st.order.slice(),hidden:{...st.hidden}};
  const menu=document.getElementById('gridCols-'+key);
  if(menu)menu.innerHTML=gridColsPopoverBodyHtml(key);
  toggleDD('gridCols-'+key);
}
function gridColsPopoverBodyHtml(key){
  const def=GRID_DEFS[key];
  const items=gridColsDraft.order.map(k=>{
    const c=def.cols.find(cc=>cc.key===k);
    if(!c)return '';
    const hidden=!!gridColsDraft.hidden[k];
    return `<div class="grid-col-item" draggable="true" data-key="${esc(k)}" ondragstart="gridColDragStart(event,'${esc(k)}')" ondragover="gridColDragOver(event)" ondrop="gridColDrop(event,'${esc(k)}')" ondragend="gridColDragEnd(event)">
      <span class="gci-handle">⠿</span>
      <label><input type="checkbox" ${hidden?'':'checked'} onchange="gridColsToggleVisDraft('${esc(k)}')"> ${esc(c.label)}</label>
    </div>`;
  }).join('');
  return `<div class="gcp-title">Colunas — arraste para reordenar</div>${items}
    <div class="grid-cols-actions">
      <button class="btn secondary" style="flex:1;min-height:32px;font-size:11px" onclick="gridColsResetDraft('${key}')">Restaurar padrão</button>
      <button class="btn primary" style="flex:1;min-height:32px;font-size:11px" onclick="gridColsSave()">Salvar</button>
    </div>`;
}
function renderGridColsPopoverBody(){
  const el=document.getElementById('gridCols-'+gridColsDraftKey);
  if(el)el.innerHTML=gridColsPopoverBodyHtml(gridColsDraftKey);
}
function gridColsToggleVisDraft(k){gridColsDraft.hidden[k]=!gridColsDraft.hidden[k];renderGridColsPopoverBody()}
function gridColsResetDraft(key){
  const def=GRID_DEFS[key];
  gridColsDraft={order:def.cols.map(c=>c.key),hidden:{}};
  renderGridColsPopoverBody();
}
function gridColsSave(){
  GRID_COLS_STATE[gridColsDraftKey]={order:gridColsDraft.order.slice(),hidden:{...gridColsDraft.hidden}};
  saveGridColsState();
  toggleDD('gridCols-'+gridColsDraftKey);
  renderControle();
  toast('Colunas atualizadas.','ok');
}
function gridColDragStart(ev,key){gridDragKey=key;ev.currentTarget.classList.add('dragging');ev.dataTransfer.effectAllowed='move'}
function gridColDragOver(ev){ev.preventDefault()}
function gridColDragEnd(ev){ev.currentTarget.classList.remove('dragging')}
function gridColDrop(ev,targetKey){
  ev.preventDefault();
  if(!gridDragKey||gridDragKey===targetKey)return;
  const order=gridColsDraft.order;
  const from=order.indexOf(gridDragKey);
  const to=order.indexOf(targetKey);
  if(from<0||to<0)return;
  order.splice(from,1);
  order.splice(to,0,gridDragKey);
  gridDragKey=null;
  renderGridColsPopoverBody();
}

/* ---- Resumo (agrupamentos) dentro de Base_Tubulação ---- */
function resumoGroupOptions(){return [['descricao','Descrição'],['dn','DN'],['folha','Folha'],['item','Item']]}
function setResumoGroupBy(v){resumoGroupBy=v;renderResumoPanel('baseTubInner')}
function renderResumoPanel(mountId){
  const mount=document.getElementById(mountId);
  if(!mount)return;
  const rows=CONTROLE.baseTubulacao;
  const groups={};
  rows.forEach(r=>{
    const k=String(r[resumoGroupBy]??'—');
    if(!groups[k])groups[k]={count:0,qtd:0,pesoKg:0,pesoT:0};
    groups[k].count++;
    groups[k].qtd+=(+r.qtdPrevista||0);
    groups[k].pesoKg+=(+r.pesoTotal||0);
    groups[k].pesoT+=(+r.pesoTotalT||0);
  });
  const keys=Object.keys(groups).sort();
  const totals=keys.reduce((a,k)=>({count:a.count+groups[k].count,qtd:a.qtd+groups[k].qtd,pesoKg:a.pesoKg+groups[k].pesoKg,pesoT:a.pesoT+groups[k].pesoT}),{count:0,qtd:0,pesoKg:0,pesoT:0});
  const optsHtml=resumoGroupOptions().map(([v,l])=>`<option value="${v}" ${v===resumoGroupBy?'selected':''}>${l}</option>`).join('');
  const dimLabel=resumoGroupOptions().find(o=>o[0]===resumoGroupBy)[1];
  const rowsHtml=keys.map(k=>`<tr><td>${esc(k)}</td><td>${groups[k].count}</td><td>${fmtNum(groups[k].qtd)}</td><td>${fmtNum(groups[k].pesoKg)}</td><td>${fmtNum(groups[k].pesoT)}</td></tr>`).join('');
  mount.innerHTML=`
    <p class="cad-note">Agrupamento das ${rows.length} linha(s) da Base de Quantidades.</p>
    <div class="qfield2" style="max-width:260px;margin-bottom:14px"><label>Agrupar por</label>
      <select onchange="setResumoGroupBy(this.value)">${optsHtml}</select>
    </div>
    <div style="overflow-x:auto"><table class="resumo-pivot"><thead><tr><th>${esc(dimLabel)}</th><th>Qtd. linhas</th><th>Qtd. Prevista</th><th>Peso Total (kg)</th><th>Peso Total (t)</th></tr></thead>
    <tbody>${rowsHtml}<tr class="pivot-total"><td>TOTAL</td><td>${totals.count}</td><td>${fmtNum(totals.qtd)}</td><td>${fmtNum(totals.pesoKg)}</td><td>${fmtNum(totals.pesoT)}</td></tr></tbody></table></div>`;
}

/* ---- Histograma (horas por item de mão de obra — Ordem de Serviço) ---- */
let histogramaMode='grafico';
function setHistogramaMode(m){histogramaMode=m;gridEditingKey=null;gridEditingId=null;renderControle()}
function renderHistogramaView(){
  document.getElementById('controleBody').innerHTML=`
    <div class="chips" style="margin-bottom:14px">
      <button class="chip ${histogramaMode==='grafico'?'active':''}" onclick="setHistogramaMode('grafico')">📊 Gráfico</button>
      <button class="chip ${histogramaMode==='dados'?'active':''}" onclick="setHistogramaMode('dados')">📋 Dados</button>
    </div>
    <div id="histogramaInner"></div>`;
  if(histogramaMode==='dados'){
    renderGrid('ordemServico','histogramaInner');
  }else{
    document.getElementById('histogramaInner').innerHTML=`<p class="cad-note">Total de horas histórico (Tot. Hist.) por item de mão de obra — Ordem de Serviço. Use "📋 Dados" para editar, importar ou exportar esta base.</p><div id="histogramaChartEl"></div>`;
    histogramaChart=null;
    renderHistogramaChart();
  }
}
function renderHistogramaChart(){
  const el=document.getElementById('histogramaChartEl');
  if(!el)return;
  const rows=[...CONTROLE.ordemServico].sort((a,b)=>(+b.totHist||0)-(+a.totHist||0));
  const categories=rows.map(r=>String(r.item||'').replace(/^\d+\s*/,''));
  const data=rows.map(r=>round2(+r.totHist||0));
  const opts={
    chart:{type:'bar',height:460,toolbar:{show:true}},
    series:[{name:'Tot. Hist. (h)',data}],
    xaxis:{categories,labels:{rotate:-45,style:{fontSize:'10px'}}},
    colors:['#002B5C'],
    dataLabels:{enabled:true,formatter:v=>fmtNum(v)},
    plotOptions:{bar:{borderRadius:4,columnWidth:'60%'}}
  };
  if(histogramaChart){histogramaChart.updateOptions(opts,true,true)}
  else{histogramaChart=new ApexCharts(el,opts);histogramaChart.render()}
}
